FVector GetMovementBaseTangentialVelocity(const FMovementBaseInterfaceData* MovementBase, const FName BoneName, const FVector& WorldLocation)
{
	if (IsDynamicBase(MovementBase))
	{
		if (const FBodyInstance* BodyInstance = MovementBase->GetBodyInstanceOwner()->GetBodyInstance(BoneName))
		{
			const FVector BaseAngVelInRad = BodyInstance->GetUnrealWorldAngularVelocityInRadians();
			if (!BaseAngVelInRad.IsNearlyZero())
			{
				FVector BaseLocation;
				FQuat BaseRotation;
				if (GetMovementBaseTransform(MovementBase, BoneName, BaseLocation, BaseRotation))
				{
					const FVector RadialDistanceToBase = WorldLocation - BaseLocation;
					const FVector TangentialVel = BaseAngVelInRad ^ RadialDistanceToBase;
					return TangentialVel;
				}
			}
		}

		const FBodyInstance* BodyInstance = MovementBase->GetBodyInstanceOwner()->GetBodyInstance();
		const FVector BaseAngVelInRad = BodyInstance ? BodyInstance->GetUnrealWorldAngularVelocityInRadians() : FVector::ZeroVector;
		if (!BaseAngVelInRad.IsNearlyZero())
		{
			FVector BaseLocation;
			FQuat BaseRotation;
			if (GetMovementBaseTransform(MovementBase, BoneName, BaseLocation, BaseRotation))
			{
				const FVector RadialDistanceToBase = WorldLocation - BaseLocation;
				const FVector TangentialVel = BaseAngVelInRad ^ RadialDistanceToBase;
				return TangentialVel;
			}
		}
	}

	return FVector::ZeroVector;

inline float UCapsuleComponent::GetScaledCapsuleRadius() const
{
	const FVector& ComponentScale = GetComponentTransform().GetScale3D();
	return CapsuleRadius * UE_REAL_TO_FLOAT(ComponentScale.X < ComponentScale.Y ? ComponentScale.X : ComponentScale.Y);
}

inline float UCapsuleComponent::GetScaledCapsuleHalfHeight() const
{
	return CapsuleHalfHeight * UE_REAL_TO_FLOAT(GetComponentTransform().GetScale3D().Z);
}
